Web platform gotcha: mutating .innerText on a <textarea> does not reliably update what is displayed or copyable once the browser treats it as an editable value. Burned time debugging "missing" data that was arriving fine the whole time. Use <pre>/<div> for live logs instead.

// Don't do this for a live-updating log/debug display
const textarea = document.querySelector( 'textarea' );

// May not show up on screen
textarea.innerText += 'new line\n'; 

// Do this instead
// <pre>/<div> have no value/dirty-flag mechanism to fight
const log = document.querySelector( 'pre' );
log.innerText += 'new line\n';

Building an MCP App? Do not use <base href> to point a resource's root-relative script src at your CDN. Claude Desktop hardcodes base-uri self and silently ignores your CSP's baseUriDomains - the tag just gets blocked, no error thrown. Rewrite the URLs to absolute instead.

function absolutizeRootRelativeUrls( html, origin ) {
  return html.replace( /((?:src|href)=")\/(?!\/)/g, $1${origin}/ );
}

The rect element in SVG draws a rectangle. The element has rx and ry attributes to specify corner radius for rounded rectangles. The radius is applied to all corners. Rounded rectangles with different corner radii requires using path and calculating arcs for smooth corners.

function roundedRect( { 
  x = 0, 
  y = 0, 
  width, 
  height, 
  topLeft = 13, 
  topRight = 13, 
  bottomRight = 0, 
  bottomLeft = 0, 
  fill, 
  stroke = 'none', 
  strokeWidth, 
  className 
} ) {
  const maxRadius = Math.min( width, height ) / 2;
  [topLeft, topRight, bottomRight, bottomLeft] = [
    topLeft, topRight, bottomRight, bottomLeft
  ].map( ( r ) => Math.min( r, maxRadius ) );

  const d = [
    M ${x + topLeft} ${y},
    L ${x + width - topRight} ${y},
    A ${topRight} ${topRight} 0 0 1 ${x + width} ${y + topRight},
    L ${x + width} ${y + height - bottomRight},
    A ${bottomRight} ${bottomRight} 0 0 1 ${x + width - bottomRight} ${y + height},
    L ${x + bottomLeft} ${y + height},
    A ${bottomLeft} ${bottomLeft} 0 0 1 ${x} ${y + height - bottomLeft},
    L ${x} ${y + topLeft},
    A ${topLeft} ${topLeft} 0 0 1 ${x + topLeft} ${y},
    'Z'
  ].join( ' ' );

  const attrs = [
    d="${d}",
    fill !== undefined ? fill="${fill}" : null,
    stroke="${stroke}",
    strokeWidth !== undefined ? stroke-width="${strokeWidth}" : null,
    className ? class="${className}" : null
  ].filter( Boolean ).join( ' ' );

  return <path ${attrs} />;
}

Implementing a serverless function that creates custom charts. I started by placing an SVG template in a string literal. This evolved into creating functions that generate SVG primitives. The resulting is code that is much cleaner, more readable, and potentially more flexible.

// Example generating a text element
function text( { 
  x, 
  y, 
  text, 
  children, 
  fontSize, 
  fontWeight, 
  fill, 
  textAnchor = 'middle', 
  dominantBaseline = 'hanging', 
  className 
} ) {
  const content = children ? children.join( '' ) : text );

  return 
    <text
      x="${x}"
      y="${y}"
      text-anchor="${textAnchor}"
      dominant-baseline="${dominantBaseline}"
      ${fontSize !== undefined ? font-size="${fontSize}" : ''}
      ${fontWeight !== undefined ? font-weight="${fontWeight}" : ''}
      ${fill !== undefined ? fill="${fill}" : ''}
      ${className ? class="${className}" : ''}>
    ${content}
  </text>;
}

If you are converting SVG to PNG then you probably want to keep the font styles intact. The resvg package can accommodate this with a font configuration. The font files themselves need to be loaded into buffers. Font styles need to be applied inline - CSS does not seem to apply.

const fs = require( 'fs' );
const path = require( 'path' );

const { Resvg, initWasm } = require( '@resvg/resvg-wasm' );

let wasmReady;

async function main( params ) {
  const svg = 
    <svg
      width="640"
      height="480"
      viewBox="0 0 640 480"
      xmlns="http://www.w3.org/2000/svg">
      <style>
        text {
          font-size: 36px;
        }
      </style>
      <text
        x="320"
        y="240"
        text-anchor="middle"
        dominant-baseline="middle">
        <tspan>Hello,</tspan>
        <tspan 
          font-family="Isidora" 
          fill="${params.color ?? 'black'}">${params.name ?? 'World'}!</tspan>
      </text>
    </svg>
  ;

  if( !wasmReady ) {
    wasmReady = initWasm( fs.readFileSync( 
      path.join( dirname, 'indexbg.wasm' ) 
    ) );
  }

  await wasmReady;

  const regularBuffer = fs.readFileSync( 
    path.join( dirname, 'Roboto-Regular.ttf' ) 
  );
  const boldBuffer = fs.readFileSync( 
    path.join( dirname, 'Isidora-Bold.otf' ) 
  );

  const resvg = new Resvg( svg, {
    font: {
      fontBuffers: [regularBuffer, boldBuffer],
      loadSystemFonts: false,
      defaultFontFamily: 'Roboto',
      sansSerifFamily: 'Roboto'
    }
  } );

  return {
    statusCode: 200,
    headers: {
      'Content-Type': 'image/png'
    },
    body: Buffer.from( resvg.render().asPng() )
  };
}

Converting SVG to PNG is usually the domain of packages such as Sharp. This creates a binary dependency which complicates deployment (develop on Mac, deploy on Linux). The resvg package gives you this functionality without the binary dependency thanks to the included WASM module.

const fs = require( 'fs' );
const path = require( 'path' );

const { Resvg, initWasm } = require( '@resvg/resvg-wasm' );

let wasmReady = false;

async function main( params ) {
  const svg = 
    <svg
      width="640"
      height="480"
      viewBox="0 0 640 480"
      xmlns="http://www.w3.org/2000/svg">
      <style>
        rect {
          fill: ${params.backgroundColor ?? 'red'};
          stroke: none;
        }
      </style>
      <rect
        x="270"
        y="190"
        width="100"
        height="100"
        rx="13"
        ry="13" />
    </svg>
  ;

  if( !wasmReady ) {
    wasmReady = await initWasm( fs.readFileSync( 
      path.join( dirname, 'indexbg.wasm' ) 
    ) );
  }

  await wasmReady;

  const resvg = new Resvg( svg );

  return {
    statusCode: 200,
    headers: {
      'Content-Type': 'image/png'
    },
    body: Buffer.from( resvg.render().asPng() )
  };
}

OpenWhisk (Adobe IO Runtime) output can present whatever content type is desired. In the case of SVG that content type would be "image/svg+xml" with the body of the response being the text string representing the SVG. You can use string literals to dynamically build the SVG.

function main( params ) {
  const svg = 
    <svg
      width="640"
      height="480"
      viewBox="0 0 640 480"
      xmlns="http://www.w3.org/2000/svg">
      <style>
        rect {
          fill: ${params.backgroundColor ?? 'red'};
          stroke: none;
        }
      </style>
      <rect 
        x="${calculateX()}" 
        y="${calculateY()}" 
        width="640" 
        height="480" />
    </svg>
  ;

  return {
    statusCode: 200,
    headers: {
      'Content-Type': 'image/svg+xml'
    },
    body: svg
  };
}

A lot of setup guides make their job easy by making your job hard. They do so by having you install all manner of additional dependencies before you even know what you are doing. Adobe App Builder is one of those products. Here is my minimalist version of what is actually needed.

.
├── actions/          Root directory for serverless functions
│    └── hello.js     Test "Hello World" serverless function
├── app.config.yaml   App Builder configuraton file 
├── package.json      Node project configuration file
└── node_modules      Directory containing Node dependencies

function main( params ) {
  return {
    statusCode: 200,
    headers: {
      'Content-Type': 'application/json'
    },
    body: {
      message: Hello, ${params.name ?? 'World'}!
    }
  }
}

exports.main = main

