When exporting SVG from Illustrator, individual tspan elements will be created for text blocks with font changes. The spans include coordinate attributes, preventing the natural flow of the text. This can create unwanted spacing between words. These attributes can be removed.

function stripPosition( tag ) {
  return tag
    .replace( /\s+x="-?[\d.]+"/g, '' )
    .replace( /\s+y="-?[\d.]+"/g, '' )
    .replace( /\s+xml:space="[^"]*"/g, '' );
}

When building workflows, consider the pipeline pattern. This pattern is an array of step functions that leverage the same context object. The context is created with all the necessary keys, then passed to a step which may/not modify it, and then returns it. Repeat for each step.

// Main
import { one } from "./steps/one.js";
import { two } from "./steps/two.js";
import { three } from "./steps/three.js";

const steps = [one, two, three];

const context = {
  inputs: null,
  outputs: null,
  file: './some/file.txt',
  errors: [],
  warnings: []
};

for( const step of steps ) {
  await step( context );

  if( context.errors ) break;
}

// Step function
export async function one( context ) {
  // Do some work
  // Modify context if needed by later steps
  return context;
}

One of the interesting effects that chat normalized is a streaming flow of text as a response. This is done to alter perceived performance of the otherwise slow LLM inference process. Here is a Netlify function in JavaScript to invoke the OpenAI API and stream the results.

import OpenAI from 'openai';
import { Pinecone } from '@pinecone-database/pinecone';

export default async ( request, context ) => {
  / CORS /
  const allowed = [
    'https://kevinhoyt.com',
    'https://ketnerlake.com'
  ];
  const origin = request.headers.get( 'Origin' );

  let headers = {
    'Access-Control-Allow-Methods': 'OPTIONS, POST',
    'Access-Control-Allow-Headers': 'Content-Type, Accept, Origin',
    'Content-Type': 'application/json'
  };

  if( allowed.includes( origin ) ) {
    headers['Access-Control-Allow-Origin'] = origin;
  } else {
    return new Response( JSON.stringify( {error: 'Bot Detected'} ), {
      status: 400,
      statusText: 'Bot detected'
    } );
  }

  if( request.method === 'OPTIONS' ) {
    return new Response( 'OK', {
      headers
    } );
  }

  / Only POST for this function /
  if( request.method !== 'POST' ) {
    return new Response( JSON.stringify( {error: 'Method Not Allowed'} ), {
      status: 405,
      statusText: 'Method Not Allowed'
    } );
  }

  / Main /
  try {
    const body = await request.json();

    // Honeypot check (bots)
    if( body.honey && body.honey !== null ) {
      return new Response( JSON.stringify( {error: 'Bot Detected'} ), {
        status: 400,
        statusText: 'Bot detected'
      } );
    }

    // Validate incoming fields
    if( !body.question ) {
      return new Response( JSON.stringify( {error: 'Question is required'} ), {
        status: 400,
        statusText: 'Bad Request',
        headers
      } );
    }

    const openai = new OpenAI( {
      apiKey: process.env.OPENAIAPIKEY
    } );

    const pc = new Pinecone( {
      apiKey: process.env.PINECONEAPIKEY
    } );

    const index = pc.index( 'your-vector-store' );
    const topK = 3;

    // Create embedding for the question
    const embeddingResponse = await openai.embeddings.create( {
      model: 'text-embedding-3-small',
      input: body.question,
      dimensions: 512
    } );
    const embedding = embeddingResponse.data[0].embedding;

    // Query Pinecone for similar content
    const queryResponse = await index.query( {
      vector: embedding,
      topK: topK,
      includeMetadata: true
    } );

    // Build context from results
    let context = '';
    for( const match of queryResponse.matches ) {
      const page = match.metadata?.page ?? '?';
      const text = match.metadata?.text ?? '';
      context += [Page ${page}] ${text}\n---\n;
    }

    const instructions = 'Your instructions here (system prompt)';

    let input = Context:\n${context}\n\nQuestion: ${body.question};
    if( body.summary ) {
      input = Conversation summary:\n${body.summary}\n\n${input};
    }

    const stream = await openai.responses.create( {
      model: 'gpt-5.1',
      instructions: instructions,
      input: input,
      stream: true
    } );

    const streamHeaders = {
      ...headers,
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      'Connection': 'keep-alive'
    };

    const readable = new ReadableStream( {
      async start( controller ) {
        try {
          for await ( const event of stream ) {
            if( event.type === 'response.output_text.delta' ) {
              controller.enqueue( new TextEncoder().encode( event.delta ) );
            }
          }
          controller.close();
        } catch ( err ) {
          controller.error( err );
        }
      }
    } );

    return new Response( readable, {
      headers: streamHeaders
    } );
  } catch ( error ) {
    return new Response( JSON.stringify( {error: error.toString()} ), {
      status: 500,
      headers
    } );
  }
};

export const config = {
  path: '/api/chat'
};

Handling the click event is common in web development. Tablets and phones, do not technically have click but will respond to the event at the end of a touch. Capturing touchstart can lead to improved perceived performance on these devices. Here is how to handle both.

const touch = ( 'ontouchstart' in document.documentElement ) ? 'touchstart' : 'click';

const button = document.querySelector( 'button' );
button.addEventListener( touch, () => console.log( 'Do something' ) );

When creating charts you will often find it useful to convert a value from the data to a pixel value. Take a value in one range, and convert it to a value in another range. This is called a linear map function. Useful for micro-controller projects as well (esp. analog sensors).

function mapRange( value, inMin, inMax, outMin, outMax ) {
  return ( ( value - inMin ) * ( outMax - outMin ) ) / ( inMax - inMin ) + outMin;
}

I recently had a client whose project required putting a basic REST API in place to handle data-oriented requests. The target language was PHP for a LAMP deployment. Here is a basic PHP "Hello, World" REST API endpoint example that includes CORS with an allowed list.

<?php
$allowedorigins = [
  'https://example.com',
  'https://www.example.com',
];

// CORS headers — only enforced when browser sends an Origin header (cross-origin requests).
// Empty origin means same-origin browser request or a non-browser client (curl, etc.).
$origin = $SERVER['HTTPORIGIN'] ?? '';
if ($origin !== '') {
  if (inarray($origin, $allowedorigins, true)) {
    header("Access-Control-Allow-Origin: {$origin}");
    header("Vary: Origin");
  } else {
    httpresponsecode(403);
    header("Content-Type: application/json; charset=UTF-8");
    echo jsonencode(['error' => 'Origin not allowed']);
    exit;
  }
}
header("Access-Control-Allow-Methods: GET, POST, OPTIONS");
header("Access-Control-Allow-Headers: Content-Type");

// Handle CORS preflight
if ($SERVER['REQUESTMETHOD'] === 'OPTIONS') {
  httpresponsecode(204);
  exit;
}

// Check method
$method = $SERVER['REQUESTMETHOD'];

// Handle GET
if ($method === 'GET') {
  header("Content-Type: text/plain; charset=UTF-8");
  $name = isset($GET['name']) && $GET['name'] !== '' ? $GET['name'] : null;
  echo $name ? "Hello, {$name}" : "Hello, World";
  exit;
}

// Handle POST
if ($method === 'POST') {
  header("Content-Type: application/json; charset=UTF-8");
  $raw = filegetcontents('php://input');
  $data = jsondecode($raw, true);
  $name = isset($data['name']) && $data['name'] !== '' ? $data['name'] : null;
  echo jsonencode(['message' => $name ? "Hello, {$name}" : "Hello, World"]);
  exit;
}

// Other methods not allowed
header("Content-Type: application/json; charset=UTF-8");
httpresponsecode(405);
echo jsonencode(['error' => 'Method not allowed']);

A honey pot is a means to prevent bots from submitting forms. A seemingly valid input field is hidden by CSS. Bots will read the code, and put content into the field - humans will not. Validation checks for content in the field. If there is content, then a bot is using the form.

<input id="honey" name="company_name" placeholder="Company name" type="text" />

#honey {
  display: none;
}

I am not sure if this is considered old-school or modern, but you can also use span elements to control wrapping with a good degree of precision. Toggle from display: inline to display: block as needed at media query break points. This also works well in i18n situations.

  <h1>
    <span>Modern Design.</span>
    <span>AI Enabled.</span>
    <span>Robust Tooling.</span>
  </h1>

  / Inline until does not fit /
  h1 span {
    display: inline;
  }

  @media screen and ( max-width: 640px ) {
    / Move last span to new line /
    h1 span:last-of-type {
      display: block
    }
  }    

  @media screen and ( max-width: 480px ) {
    / First span on own line /
    h1 span:first-of-type {
      display: block
    }

    / Remaining spans on second line /
    h1 span:last-of-type {
      display: inline;
    }
  }      

  @media screen and ( max-width: 375px ) {  
    / Put all spans on new line /
    h1 span {
      display: block;
    }
  }

A client that wanted an animated typing effect on their website. A word would be typed out. Pause. The word would be deleted (backspace). Iterate an array of options. Claude went with setTimeout(). I prefer requestAnimationFrame() and a state machine. Full code in a Gist.

step( now ) {
  if( !this.messages.length ) return;

  const word = String( this.messages[this.index] ?? '' );

  switch( this.phase ) {
    case 'TYPING': {
      if( this.character < word.length ) {
        this.character += 1;
        this.$span.textContent = word.slice( 0, this.character );
        this.nextAt = now + this.TYPINGMS;
      } else {
        this.phase = 'PAUSEFULL';
        this.nextAt = now + this.PAUSEFULL;
      }
      break;
    }

    case 'PAUSEFULL': {
      this.phase = 'DELETING';
      this.nextAt = now + this.DELETINGMS;
      break;
    }

    case 'DELETING': {
      if( this.character > 0 ) {
        this.character -= 1;
        this.$span.textContent = word.slice( 0, this.character );
        this.nextAt = now + this.DELETINGMS;
      } else {
        this.phase = 'PAUSEEMPTY';
        this.nextAt = now + this.PAUSEEMPTY;
      }
      break;
    }

    case 'PAUSEEMPTY': {
      this.index = ( this.index + 1 ) % this.messages.length;
      this.phase = 'TYPING';
      this.nextAt = now + this.TYPINGMS;
      break;
    }
  }
}

One last CSS snippet for good measure. Yes, this site required a lot of complex gradients. This CSS rule will fill the background of a container element with a linear gradient. On the diagonal. Based on solid colors, but nearly transparent. Thanks again color-mix function!

.gradient-box {
  background: 
    linear-gradient(
      to bottom right, 
      color-mix(
        in srgb, 
        var( --brand-purple ) 12%, 
        transparent
      ), 
      color-mix( 
        in srgb, 
        var( --brand-pink ) 12%, 
        transparent
      )
    );
}

Not perhaps as equally as impressive as the color-mix function, but sometimes you need to fill a span of text with a gradient color. Not the background; the text itself. The tricky part here is in getting the clipping properties set correctly. CSS is so powerful these days.

.gradient-text {
  background: 
    linear-gradient(
      90deg, 
      var( --brand-purple ), 
      var( --brand-pink )
    );
  background-clip: text;  
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

Needed to fill the background of a website hero section with a complex gradient. Two large radial gradients, one in the top-right area, and one in the bottom-left area. Large enough to overlap considerably. Nearly transparent, but based on solid colors. I give you, color-mix.

.gradient-hero {
  background:
    radial-gradient(
      ellipse at 110% -5%, 
      color-mix(
        in srgb, 
        var( --brand-purple ) 25%, 
        transparent
      ) 0%, 
      transparent 55%
    ),
    radial-gradient( 
      ellipse at -10% 105%, 
      color-mix( 
        in srgb, 
        var( --brand-cyan ) 18%, 
        transparent
      ) 0%, 
      transparent 55%
    );
}

/ Bonus: Fade to white at the bottom /
.gradient-hero::after {
  background: linear-gradient( to bottom, transparent, white );
  bottom: 0;
  content: '';
  height: 150px;
  left: 0;
  pointer-events: none;
  position: absolute;
  right: 0;
}
